#include <iostream>
#include <vector>
#include <map>
#include <cassert>
#include <cstdint>
using namespace std;

const int MOD = 1000000007;

class Mod {
public:
    int val;

    Mod(long long v = 0) {
        v %= MOD;
        if (v < 0) v += MOD;
        val = static_cast<int>(v);
    }

    static int mod_inverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return val; }

    Mod& operator+=(const Mod& other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    Mod& operator-=(const Mod& other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
        return static_cast<unsigned>(x % m);
    }

    Mod& operator*=(const Mod& other) {
        val = fast_mod(static_cast<uint64_t>(val) * other.val);
        return *this;
    }

    Mod& operator/=(const Mod& other) {
        return *this *= other.mod_inverse();
    }

    friend Mod operator+(const Mod& a, const Mod& b) { return Mod(a) += b; }
    friend Mod operator-(const Mod& a, const Mod& b) { return Mod(a) -= b; }
    friend Mod operator*(const Mod& a, const Mod& b) { return Mod(a) *= b; }
    friend Mod operator/(const Mod& a, const Mod& b) { return Mod(a) /= b; }

    Mod& operator++() {
        val = (val == MOD - 1) ? 0 : val + 1;
        return *this;
    }

    Mod& operator--() {
        val = (val == 0) ? MOD - 1 : val - 1;
        return *this;
    }

    Mod operator++(int) { Mod tmp = *this; ++*this; return tmp; }
    Mod operator--(int) { Mod tmp = *this; --*this; return tmp; }

    Mod operator-() const { return val ? MOD - val : 0; }

    bool operator==(const Mod& other) const { return val == other.val; }
    bool operator!=(const Mod& other) const { return val != other.val; }

    Mod mod_inverse() const { return Mod::mod_inverse(val); }

    Mod power(long long exp) const {
        assert(exp >= 0);
        Mod base = *this, res = 1;
        while (exp > 0) {
            if (exp & 1) res *= base;
            base *= base;
            exp >>= 1;
        }
        return res;
    }
};

const int MAX_N = 7;
int N;
Mod P[MAX_N][MAX_N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            P[i][j] = Mod(p) / Mod(100);
        }
    }

    vector<vector<int>> masks_by_pop(MAX_N + 1);
    vector<int> idx(1 << N, -1);

    for (int mask = 0; mask < (1 << N); ++mask) {
        int pop = __builtin_popcount(mask);
        idx[mask] = masks_by_pop[pop].size();
        masks_by_pop[pop].push_back(mask);
    }

    map<long long, Mod> dp;
    dp[1LL << idx[0]] = Mod(1);

    for (int step = 0; step < N; ++step) {
        map<long long, Mod> new_dp;

        for (int cur = 0; cur < (1 << N); ++cur) {
            Mod prod = Mod(1);
            for (int j = 0; j < N; ++j) {
                if ((cur >> j) & 1) {
                    prod *= P[step][j];
                } else {
                    prod *= (Mod(1) - P[step][j]);
                }
            }

            for (const auto& [state, prob] : dp) {
                long long cur_state = state;
                Mod cur_prob = prob;

                long long next_state = 0;

                for (int mask : masks_by_pop[step]) {
                    if ((cur_state >> idx[mask]) & 1) {
                        for (int i = 0; i < N; ++i) {
                            if (((cur >> i) & 1) && !((mask >> i) & 1)) {
                                next_state |= 1LL << idx[mask | (1 << i)];
                            }
                        }
                    }
                }

                new_dp[next_state] += cur_prob * prod;
            }
        }

        dp = move(new_dp);
    }

    Mod answer = Mod(0);
    long long full = (1LL << N) - 1;

    for (const auto& [state, prob] : dp) {
        if ((state >> idx[full]) & 1) {
            answer += prob;
        }
    }

    cout << (int)answer << '\n';
    return 0;
}
